/* * */

import { BaseDocumentSchema } from '@tmlmobilidade/go-types-shared';
import { z } from 'zod';

import { MetricSchema } from './legacy/index.js';

/* * */

/** Stored metric results are generated by workers, without user audit fields. */
export const MetricDocumentSchema = MetricSchema.and(BaseDocumentSchema.pick({
	_id: true,
	created_at: true,
	updated_at: true,
}));

export type MetricDocument = z.infer<typeof MetricDocumentSchema>;
